let forms, N, stillT;
const ANIM_MODE = true;
const FRAMES_PER_SECOND = 30;
const FRAMES_TRANSITION = 60;

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
	frameRate(FRAMES_PER_SECOND);
  describe("digital replication of Bridget Riley's inverted grid and circle art");
	noStroke();

	N = ~~random(2, 5); // -> 2, 3, 4
	forms = [];
	forms.push(genForm({x: 0, y: 0, s: S}, N));
	forms.push(genForm({x: 0, y: 0, s: S}, N));
	stillT = random(); // for still
}

function draw() {
	blendMode(BLEND)
	background("rgb(200,200,190)");
	blendMode(DIFFERENCE);
	fill(255)

	// force screen invert on 6, 10, 14, ... to let the inner circle be "black"
	if (forms[0].xPosArr.length/2 % 2) rect(0, 0, width, height);

	// new form
	if (frameCount % FRAMES_TRANSITION === 0) {
		// console.log("new gen");
		forms[0] = forms[1];
		forms[1] = genForm({x: 0, y: 0, s: S}, N);
		stillT = random();
	}

	let t = (frameCount % FRAMES_TRANSITION) / FRAMES_TRANSITION; // 0..1
	// t = (sin(t*TWO_PI)+1)/2; // 0..1..0
	const form = genTransition(forms[0], forms[1], ANIM_MODE ? t : stillT); // // console.log(nf(t, 0, 2));
	drawForm(form);
}

// https://discord.com/channels/820953351817789480/820953352561098787/1291276136478675004
function genForm(sq, N = 3) {
	let xPosArr = new Array(N*2-1);
	let yPosArr = new Array(N*2-1);
	let xVisArr = new Array(N*2-1);
	let yVisArr = new Array(N*2-1);

	const f = 0.6;
	let x = sq.x; let y = sq.y; let s = sq.s;
	for (let i = 0; i < N; i++) {
		xPosArr[i] = x;
		xPosArr[N*2-1-i] = x + s;
		yPosArr[i] = y;
		yPosArr[N*2-1-i] = y + s;
		xVisArr[i] = true; // random() > 1/N;
		xVisArr[N*2-1-i] = true;
		yVisArr[i] = true; // random() > 1/N;
		yVisArr[N*2-1-i] = true;

		const dx = ~~random(10, s*f)
		const dy = ~~random(10, s*f);
		x += dx;
		y += dy;
		let ds = ~~random(10, s*f);
		s -= max(dx + ds, dy + ds);
	}

	// make one random x / y unvisible // rare chance of no visual change, when rand == last item 
	// xVisArr[~~random(xVisArr.length)] = false;
	// yVisArr[~~random(yVisArr.length)] = false;
	if (random() < 0.5) { // 80% probability
		// make rect over last circle invisible
		if (random() < 0.5) {
			xVisArr[N-1] = false;
		} else {
			yVisArr[N-1] = false;
		}
	}

	return {xPosArr, yPosArr, xVisArr, yVisArr};
}

function genTransition(form1, form2, t) {
	const N = form1.xPosArr.length;
	var xPosArr = new Array(N-1);
	var yPosArr = new Array(N-1);
	var xVisArr = new Array(N-1);
	var yVisArr = new Array(N-1);

	for (let i = 0; i < N; i++) {
		// lerp position
		xPosArr[i] = lerp(form1.xPosArr[i], form2.xPosArr[i], easeInOutElastic(t));
		yPosArr[i] = lerp(form1.yPosArr[i], form2.yPosArr[i], easeInOutCubic(t));
		// take visibility status from 1st form
		xVisArr[i] = form1.xVisArr[i];
		yVisArr[i] = form1.yVisArr[i];
	}

	return {xPosArr, yPosArr, xVisArr, yVisArr};
}

function drawForm(form) {
	var xPosArr = form.xPosArr;
	var yPosArr = form.yPosArr;

	// draw circles
	var N = ~~(xPosArr.length/2);
	for (let i = 0; i < N; i++) {
		var x = xPosArr[i];
		const y = yPosArr[i];
		const s = xPosArr[N*2-1-i] - x;
		circle(x+s/2, y+s/2, s)
	}

	// draw rectangles
	for (let i = 0; i < xPosArr.length-1; i+=2) {
		var x = Math.round(xPosArr[i]);
		const w = Math.round(xPosArr[i+1]-x);
		// console.log(`vis ${form.xVisArr[i]}, x ${x}, w ${w}`)
		if (form.xVisArr[i]) rect(x, 0, w, height);
	}
	for (let i = 1; i < yPosArr.length-1; i+=2) {
		var y = Math.round(yPosArr[i]);
		const h = Math.round(yPosArr[i+1]-y);
		// console.log(`vis ${form.yVisArr[i]}, y ${y}, h ${h}`)
		if (form.yVisArr[i]) rect(0, y, width, h);
	}
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}
